def clean_style(style):
    style.font.name='Times New Roman';style.font.color.rgb=RGBColor(0,0,0)
    rp=style.element.get_or_add_rPr()
    for tag in ['spacing','caps','smallCaps','u']:
        for node in list(rp.findall(qn('w:'+tag))):rp.remove(node)
    fonts=rp.find(qn('w:rFonts'))
    if fonts is not None:
        for key in list(fonts.attrib):
            if 'theme' in key.lower():del fonts.attrib[key]
        for key in ['ascii','hAnsi','eastAsia','cs']:fonts.set(qn('w:'+key),'Times New Roman')
    color=rp.find(qn('w:color'))
    if color is not None:
        for key in list(color.attrib):
            if key!=qn('w:val'):del color.attrib[key]
    pp=style.element.find(qn('w:pPr'))
    if pp is not None:
        for node in list(pp.findall(qn('w:pBdr'))):pp.remove(node)

class Paper:
    def __init__(self,number,name,title,subtitle='',court=True,counter=False):
        self.number=number;self.name=name;self.text=[];self.doc=Document();self.court=court
        s=self.doc.sections[0];s.page_width=Cm(21);s.page_height=Cm(29.7)
        s.top_margin=Cm(1.8);s.bottom_margin=Cm(1.8);s.left_margin=Cm(2.4);s.right_margin=Cm(1.8);s.footer_distance=Cm(.8)
        for st in self.doc.styles:
            try:clean_style(st)
            except AttributeError:pass
        normal=self.doc.styles['Normal'];normal.font.size=Pt(12)
        normal.paragraph_format.line_spacing=1.08;normal.paragraph_format.space_after=Pt(6)
        normal.paragraph_format.widow_control=True
        lang=OxmlElement('w:lang');lang.set(qn('w:val'),'uk-UA' if number!=7 else 'ru-RU');normal.element.get_or_add_rPr().append(lang)
        for n in ['Title','Subtitle','Heading 1','Heading 2']:
            st=self.doc.styles[n];st.base_style=normal;st.font.size=Pt(13 if n!='Subtitle' else 12)
            st.font.bold=n!='Subtitle';st.font.italic=False
            st.paragraph_format.space_before=Pt(10);st.paragraph_format.space_after=Pt(5)
            st.paragraph_format.keep_with_next=True
        if court:
            who='Відповідач за первісним позовом' if not counter else 'Позивач за зустрічним позовом'
            head=[
            ('До Вінницького міського суду Вінницької області',True),
            ('21050, м. Вінниця, вул. Грушевського, 17',False),
            ('Справа № 127/20805/26',True),('Провадження № 2/127/5742/26',False),('Суддя Бессараб Н. М.',False),
            ('',False),(who,True),('Подольський Андрій Юрійович',True),('РНОКПП 3138306873',False),
            ('Адреса реєстрації: 21022, м. Вінниця,',False),('вул. Тарногородського, буд. 48А, кв. 90',False),
            ('Електронний кабінет ЄСІТС зареєстровано',False),('andrii.podolskyi@gmail.com; +380930808888',False),
            ('',False),('Інша сторона: АТ «АКЦЕНТ-БАНК»',True),('ЄДРПОУ 14360080',False),
            ('49074, м. Дніпро, вул. Батумська, 11',False),('Електронний кабінет ЄСІТС зареєстровано',False)]
            for t,b in head:
                pp=self.p(t,bold=b,keep=True,size=11)
                pp.paragraph_format.left_indent=Cm(7.0);pp.paragraph_format.space_after=Pt(0);pp.paragraph_format.line_spacing=1.0
        self.p(title,style='Title',align=WD_ALIGN_PARAGRAPH.CENTER,bold=True,keep=True)
        if subtitle:self.p(subtitle,style='Subtitle',align=WD_ALIGN_PARAGRAPH.CENTER,keep=True)
        footer=s.footer.paragraphs[0];footer.alignment=WD_ALIGN_PARAGRAPH.CENTER
        fld=OxmlElement('w:fldSimple');fld.set(qn('w:instr'),'PAGE');footer._p.append(fld)
        self.doc.core_properties.title=title+' '+subtitle
        self.doc.core_properties.author='Подольський Андрій Юрійович' if number!=7 else 'Робоча підготовка до засідання'
        self.doc.core_properties.comments=''
    def p(self,text,bold=False,style=None,align=None,keep=False,size=12,number=None):
        para=self.doc.add_paragraph(style=style)
        rr=para.add_run(text);rr.bold=bold;rr.font.name='Times New Roman';rr.font.size=Pt(size);rr.font.color.rgb=RGBColor(0,0,0)
        rp=rr._r.get_or_add_rPr();rf=rp.find(qn('w:rFonts'))
        if rf is not None:
            for key in list(rf.attrib):
                if 'theme' in key.lower():del rf.attrib[key]
            for key in ['ascii','hAnsi','eastAsia','cs']:rf.set(qn('w:'+key),'Times New Roman')
        para.paragraph_format.keep_with_next=keep
        para.paragraph_format.keep_together=True
        if align is not None:para.alignment=align
        if number is not None:para.paragraph_format.left_indent=Cm(.6);para.paragraph_format.first_line_indent=Cm(-.6)
        self.text.append(text);return para
    def h(self,text):return self.p(text,bold=True,style='Heading 1',keep=True)
    def request(self,items):
        self.p('ПРОШУ СУД',bold=True,align=WD_ALIGN_PARAGRAPH.CENTER,keep=True)
        for i,t in enumerate(items,1):self.p(f'{i}. {t}',number=i)
    def sign(self):
        self.p('01 жовтня 2026 року',keep=True)
        self.p('Подольський Андрій Юрійович                         __________________')
    def table(self,headers,rows,widths):
        table=self.doc.add_table(rows=1,cols=len(headers));table.autofit=False
        table.style='Table Grid'
        for c,w in zip(table.columns,widths):c.width=Cm(w)
        trPr=table.rows[0]._tr.get_or_add_trPr();repeat=OxmlElement('w:tblHeader');trPr.append(repeat)
        for c,h,w in zip(table.rows[0].cells,headers,widths):c.width=Cm(w);c.text=str(h)
        for row in rows:
            cells=table.add_row().cells
            for c,v,w in zip(cells,row,widths):c.width=Cm(w);c.text=str(v)
        for i,row in enumerate(table.rows):
            prop=row._tr.get_or_add_trPr();prop.append(OxmlElement('w:cantSplit'))
            for cell in row.cells:
                for p in cell.paragraphs:
                    p.paragraph_format.space_after=Pt(3);p.paragraph_format.space_before=Pt(3);p.paragraph_format.line_spacing=1.0
                    for r in p.runs:r.font.name='Times New Roman';r.font.size=Pt(10.5);r.font.bold=i==0;r.font.color.rgb=RGBColor(0,0,0)
        self.text.extend([' | '.join(map(str,headers))]+[' | '.join(map(str,r)) for r in rows])
    def save(self,folder):
        stem=f'{self.number:02}_{self.name}'
        dest=folder/(stem+'.docx')
        if ONLY is None or ONLY==self.number:
            self.doc.save(dest)
            (folder/(stem+'.txt')).write_text('\n\n'.join(self.text),encoding='utf-8')
        FILES.append({'number':self.number,'name':self.name,'docx':str(dest.relative_to(ROOT)),'txt':str(dest.with_suffix('.txt').relative_to(ROOT)),'role':'court' if self.number<5 else 'attachment' if self.number<7 else 'private'})

